function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fillBleed(0.3);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(200, 400);
  brush.endShape(true);

  // Hills (green)
  brush.fill("#8a995f");
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.vertex(200, 400);
  brush.endShape(true);

  // Sun
  brush.fill("#ff9900");
  brush.beginShape();
  brush.vertex(150, 150);
  brush.vertex(250, 50);
  brush.vertex(100, 250);
  brush.endShape(true);

  // Clouds (lighter green)
  brush.fill("#a8c280");
  brush.beginShape();
  brush.vertex(100, 100);
  brush.vertex(300, 100);
  brush.vertex(200, 300);
  brush.endShape(true);

  // Trees (lighter green)
  brush.fill("#b0c48f");
  brush.beginShape();
  brush.vertex(50, 150);
  brush.vertex(150, 150);
  brush.vertex(100, 250);
  brush.endShape(true);

  // Hills (darker green)
  brush.fill("#6a7c45");
  brush.beginShape();
  brush.vertex(0, 250);
  brush.vertex(400, 250);
  brush.vertex(200, 400);
  brush.endShape(true);

  // Hills (lighter green again)
  brush.fill("#a8c280");
  brush.beginShape();
  brush.vertex(0, 300);
  brush.vertex(400, 300);
  brush.vertex(200, 450);
  brush.endShape(true);

  // Hills (darker green again)
  brush.fill("#6a7c45");
  brush.beginShape();
  brush.vertex(0, 350);
  brush.vertex(400, 350);
  brush.vertex(200, 500);
  brush.endShape(true);
}  
